import { contrastRatio } from './scan';
import type { QrTypeId } from './types';

/**
 * Ready-made logos for the centre of the code, drawn as app-style tiles: a rounded square in the
 * brand's (or the type's) colour with the glyph on top. Brand paths come from Simple Icons (CC0)
 * and generic glyphs from Lucide (ISC); the list leans on what Brazilian QR codes link to.
 */
export interface LogoPreset {
  id: string;
  label: string;
  /** A generic glyph (stroked, Lucide) or a brand mark (filled, Simple Icons). */
  kind: 'icon' | 'brand';
  color: string;
  /** Types this logo fits, listed first when one of them is being designed. */
  types: QrTypeId[];
  /** The glyph's markup, on a 24×24 canvas unless viewBox says otherwise. */
  glyph: string;
  /** Glyph colour; by default white, or near-black on light tiles. */
  ink?: string;
  /** How much of the 64-unit tile the glyph spans (32 by default). */
  glyphSize?: number;
  /** Side of the glyph's own canvas, when it isn't 24. */
  viewBox?: number;
  /** The glyph carries its own colours (Google's G), so no fill is applied. */
  multicolor?: boolean;
  /** An outline for light tiles that would otherwise vanish on white. */
  border?: string;
}

