/** The tile as a self-contained SVG data URL, the same shape an uploaded logo takes. */
export function logoPresetDataUrl(preset: LogoPreset): string {
  // White marks read on dark tiles; light brand colours get a dark mark unless the preset says otherwise.
  const ink = preset.ink ?? (contrastRatio(preset.color, '#ffffff') >= 2.5 ? '#ffffff' : '#171717');
  const paint = preset.multicolor
    ? ''
    : preset.kind === 'icon'
      ? `fill="none" stroke="${ink}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"`
      : `fill="${ink}"`;
  const size = preset.glyphSize ?? 32;
  const offset = (64 - size) / 2;
  const scale = Math.round((size / (preset.viewBox ?? 24)) * 10000) / 10000;
  const outline = preset.border ? ` stroke="${preset.border}" stroke-width="1.5"` : '';
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="256" height="256">` +
    `<rect x="0.75" y="0.75" width="62.5" height="62.5" rx="14.5" fill="${preset.color}"${outline}/>` +
    `<g transform="translate(${offset} ${offset}) scale(${scale})" ${paint}>${preset.glyph}</g></svg>`;
  return `data:image/svg+xml;base64,${btoa(svg)}`;
}

/**
 * Every preset: the simple icons first, then the brands. Within each group the ones that fit the
 * given type lead, and the rest keep their order.
 */
export function logoPresetsFor(type: QrTypeId): LogoPreset[] {
  const fitsFirst = (presets: LogoPreset[]) => [
    ...presets.filter((preset) => preset.types.includes(type)),
    ...presets.filter((preset) => !preset.types.includes(type)),
  ];
  return [
    ...fitsFirst(LOGO_PRESETS.filter((preset) => preset.kind === 'icon')),
    ...fitsFirst(LOGO_PRESETS.filter((preset) => preset.kind === 'brand')),
  ];
}
